+  'Swahili',
+  'Yoruba',
+  'Zulu',
+  'Amharic',
+  'Hausa',
+  'Igbo',
+  'Amazigh',
+  'Shona',
+  'Fulani',
+  'Malagasy',
+  'Oromo'
+];
+
+export default function AddScreen() {
+  const [formData, setFormData] = useState({
