+      Alert.alert('Error', 'Please fill in all fields and select a cover image.');
+      return;
+    }
+    if (chapters.length === 0) {
+      Alert.alert('Error', 'Please add at least one chapter.');
+      return;
+    }
+
+    try {
+      setLoading(true);
+      const token = await SecureStore.getItemAsync('authToken');
+
+      const data = new FormData();
+      data.append('title', formData.title);
+      data.append('author', formData.author);
+      data.append('reciter', formData.reciter);
+      data.append('description', formData.description);
+
+      // cover image
+      data.append('coverImage', {
+        uri: formData.coverImage.uri,
+        type: 'image/jpeg',
+        name: 'cover.jpg',
+      });
+
+      // chapters
+      chapters.forEach((chapter, index) => {
