+          data.append(`chapters[${index}][audio]`, {
+            uri: chapter.audio.uri,
+            type: chapter.audio.mimeType || 'audio/mpeg',
+            name: chapter.audio.name || `chapter${index + 1}.mp3`,
+          });
+        }
+      });
+
+      const response = await fetch('http://<YOUR_BACKEND_URL>/books', {
+        method: 'POST',
+        headers: {
+          Authorization: `Bearer ${token}`,
