+        placeholder="Title"
+        value={formData.title}
+        onChangeText={(text) => setFormData({ ...formData, title: text })}
+        style={{ borderWidth: 1, padding: 10, marginBottom: 10 }}
+      />
+      <TextInput
+        placeholder="Author"
+        value={formData.author}
+        onChangeText={(text) => setFormData({ ...formData, author: text })}
+        style={{ borderWidth: 1, padding: 10, marginBottom: 10 }}
+      />
+      <TextInput
