+    form.append('category', formData.category);
+    form.append('language', formData.language);
+
+    // Append book cover
+    if (bookCoverFile) {
+      form.append('bookCover', {
+        uri: bookCoverFile.uri,
+        name: bookCoverFile.name || 'cover.jpg',
